import re


_FD1_HEADING_RE = re.compile(r"\bTABLE\s+FD-1\b.*\bSummary of Federal Debt\b", re.IGNORECASE)
_YEAR_ROW_RE = re.compile(r"^\s*(?:19|20)\d{2}\s*(?:\.{2,}|\s+)?$", re.IGNORECASE)
_NUMERIC_LINE_RE = re.compile(r"^\s*\$?(?:\d{1,3}(?:,\d{3})+|\d{4,})(?:\.\d+)?\s*$")
_TARGET_DOC_RE = re.compile(
    r"\bgross federal debt\b.*\b(?:FY|fiscal year)\s+2024\b|\b(?:FY|fiscal year)\s+2024\b.*\bgross federal debt\b",
    re.IGNORECASE,
)


def rule_fd1_latest_gross_federal_debt_total(doc: dict) -> list[dict]:
    try:
        def norm(text: str) -> str:
            return re.sub(r"\s+", " ", (text or "")).strip()

        def add_span(spans: list[dict], seen: set[str], text: str, source: dict | None = None) -> None:
            cleaned = norm(text)
            if not cleaned:
                return
            key = cleaned.lower()
            if key in seen:
                return
            seen.add(key)
            span = {"text": cleaned}
            if source is not None:
                if source.get("page_no") is not None:
                    span["page_no"] = source.get("page_no")
                if source.get("line_no") is not None:
                    span["line_no"] = source.get("line_no")
                if source.get("paragraph_no") is not None:
                    span["paragraph_no"] = source.get("paragraph_no")
            spans.append(span)

        lines = [item for item in (doc.get("lines") or []) if isinstance(item, dict)]
        if not lines:
            return []

        # Restrict to the recent bulletins that discuss FY 2024 gross federal debt.
        full_text = norm(doc.get("text") or " ".join(norm(item.get("text") or "") for item in lines))
        target_hit = bool(full_text and _TARGET_DOC_RE.search(full_text))
        if not target_hit:
            return []

        heading_idx = None
        for idx, item in enumerate(lines):
            text = norm(item.get("text") or "")
            if _FD1_HEADING_RE.search(text):
                heading_idx = idx
                break
        if heading_idx is None:
            return []

        latest_value = None
        latest_source = None
        in_annual_block = False
        captured_value_for_current_row = False

        scan_limit = min(len(lines), heading_idx + 1500)
        for idx in range(heading_idx + 1, scan_limit):
            text = norm(lines[idx].get("text") or "")
            if not text:
                continue

            if re.search(r"\bFD-2\b", text, re.IGNORECASE):
                break

            if _YEAR_ROW_RE.match(text):
                in_annual_block = True
                captured_value_for_current_row = False
                continue

            if not in_annual_block:
                continue

            if _NUMERIC_LINE_RE.match(text):
                if not captured_value_for_current_row:
                    latest_value = text.replace("$", "")
                    latest_source = lines[idx]
                    captured_value_for_current_row = True
                continue

            if captured_value_for_current_row and re.search(r"[A-Za-z]", text):
                break

        if latest_value is None:
            return []

        spans: list[dict] = []
        seen: set[str] = set()
        add_span(spans, seen, latest_value, latest_source)
        return spans
    except Exception:
        return []

import re


def rule_fd_public_debt_latest_fy(doc: dict) -> list[dict]:
    try:
        line_objs = doc.get("lines") or []
        if line_objs and isinstance(line_objs[0], dict):
            lines = [str(x.get("text", "")) for x in line_objs]
        else:
            lines = str(doc.get("text", "")).splitlines()
            line_objs = [{"text": t} for t in lines]

        def norm(text: str) -> str:
            return re.sub(r"\s+", " ", str(text or "")).strip()

        month_pat = re.compile(
            r"\b(jan|feb|mar|apr|may|jun|jul|aug|sep|sept|oct|nov|dec|"
            r"january|february|march|april|june|july|august|september|"
            r"october|november|december)\b",
            re.I,
        )
        year_pat = re.compile(r"^\s*(19|20)\d{2}\b")

        def find_start(phrases: tuple[str, ...]) -> int | None:
            for i in range(len(lines)):
                window = " ".join(norm(lines[j]) for j in range(i, min(len(lines), i + 3))).lower()
                if "table fd" not in window:
                    continue
                if not any(p in window for p in phrases):
                    continue
                if any(
                    year_pat.match(norm(lines[j])) for j in range(i + 1, min(len(lines), i + 120))
                ):
                    return i
            for i in range(len(lines) - 1):
                window = (norm(lines[i]) + " " + norm(lines[i + 1])).lower()
                if "table fd" not in window:
                    continue
                if not any(p in window for p in phrases):
                    continue
                if any(
                    year_pat.match(norm(lines[j])) for j in range(i + 1, min(len(lines), i + 120))
                ):
                    return i
            return None

        def extract_latest_row(start: int) -> dict | None:
            search_end = min(len(lines), start + 260)
            year_rows: list[int] = []
            saw_year_block = False
            for i in range(start, search_end):
                t = norm(lines[i])
                if not t:
                    continue
                if year_pat.match(t) and not month_pat.search(t):
                    year_rows.append(i)
                    saw_year_block = True
                    continue
                if saw_year_block:
                    if month_pat.search(t):
                        break
                    if t.lower().startswith("table fd"):
                        break
            if not year_rows:
                return None
            row_start = year_rows[-1]
            row_end = min(search_end, row_start + 30)
            for i in range(row_start + 1, row_end):
                if norm(lines[i]).lower().startswith("table fd"):
                    row_end = i
                    break

            span_text = "\n".join(lines[start:row_end]).strip()
            if not span_text:
                return None

            span = {"text": span_text}
            if line_objs and isinstance(line_objs[row_start], dict):
                span["page_no"] = line_objs[row_start].get("page_no")
                span["line_no"] = line_objs[row_start].get("line_no")
                span["end_page_no"] = line_objs[row_end - 1].get("page_no")
                span["end_line_no"] = line_objs[row_end - 1].get("line_no")
            return span

        spans: list[dict] = []

        # First try the modern summary table, then fall back to the older public-debt table.
        for phrases in (
            ("summary of federal debt",),
            ("debt held by the public", "interest-bearing public debt"),
        ):
            start = find_start(phrases)
            if start is None:
                continue
            span = extract_latest_row(start)
            if span is not None:
                spans.append(span)

        return spans
    except Exception:
        return []

